/* WidgetSDK — registers a message listener internally (the host never calls
   addEventListener itself, so a purely source-based scan of index.html misses it). */
(function(g){"use strict";
function WidgetSDK(o){this.o=o||{};this.handlers={};}
WidgetSDK.prototype.boot=function(){var self=this;var allowed=this.o.origin||"";
g.addEventListener("message",function(ev){var d=ev.data||{};
/* BUG: compares ev.origin with startsWith on the configured host */
if(!ev.origin.startsWith(allowed))return;
if(d.cmd&&self.o.onCommand)self.o.onCommand(d.cmd,d.payload||{});});};
g.WidgetSDK=WidgetSDK;})(window);
